/* Ordinary Nat20 builder: catalogue and sheets are server data, never client rules. */
(()=>{
 'use strict';
 const page=el('section',undefined,'view');page.id='prototype-creation';
 page.append(el('p','НОВАЯ ИГРА','eyebrow'),el('h1','Герой и приключение'));
 const mode=el('p','','hint'),notice=el('p','','hint'),form=el('form',undefined,'settings-card prototype-form'),preview=el('section',undefined,'page-card prototype-preview'),buttons=el('div',undefined,'button-row');
 notice.setAttribute('role','status');preview.setAttribute('aria-label','Подтверждённый лист героя');
 const check=el('button','Проверить лист'),start=el('button','Начать игру','primary'),back=el('button','Мои приключения'),importer=el('button','Материалы приключения и прежний мастер');
 check.type=back.type=importer.type='button';start.type='submit';buttons.append(check,start,back,importer);page.append(mode,notice,form,preview);form.append(buttons);$('campaigns').after(page);
 let catalogue=null,draft=null,revision=0,validated=-1,working=false,requestId=null;
 const structuredWorld=()=>Boolean(draft?.world_run_id);
 const fields=el('div',undefined,'prototype-fields');form.prepend(fields);const key='solo-prototype-draft',pendingKey='solo-prototype-pending',attackProfiles=new Map();
 function pendingLaunch(){try{return JSON.parse(localStorage.getItem(pendingKey));}catch{return null;}}
 function launchPayload(){const {world_run_id,source_ruleset,...payload}=draft;payload.encounter_attack_bonuses={};payload.encounter_attack_sources={};for(const id of draft.encounter_monsters||[]){if(attackProfiles.get(id)?.profile?.status!=='unbound')continue;if(Object.hasOwn(draft.encounter_attack_bonuses||{},id))payload.encounter_attack_bonuses[id]=draft.encounter_attack_bonuses[id];if(draft.encounter_attack_sources?.[id])payload.encounter_attack_sources[id]=draft.encounter_attack_sources[id];}return payload;}
 function monsterProfile(id){if(!attackProfiles.has(id)){const state={};attackProfiles.set(id,state);state.promise=api('/prototype/catalog/monsters/'+encodeURIComponent(id)).then(value=>{if(!value.attack_profile)throw new Error('Сервер не передал профиль атаки.');state.profile=value.attack_profile;return state.profile;}).catch(error=>{state.error=error;throw error;});}return attackProfiles.get(id).promise;}
 function rememberLaunch(value){try{localStorage.setItem(pendingKey,JSON.stringify(value));}catch{}}
 function saveDraft(){try{localStorage.setItem(key,JSON.stringify(draft));}catch{}}
 function remember(){revision++;validated=-1;requestId=null;localStorage.removeItem(pendingKey);start.disabled=true;if(structuredWorld()){draft.hero_confirmed=false;const consent=fields.querySelector('#prototype-hero-confirm');if(consent)consent.checked=false;}saveDraft();}
 function worldConsented(){return !structuredWorld()||(draft.rules_confirmed&&draft.hero_confirmed&&draft.background_confirmed);}
 function buttonState(){check.disabled=working||!catalogue;start.disabled=working||validated!==revision||!worldConsented()||(draft?.encounter_monsters||[]).some(id=>!attackProfiles.get(id)?.profile&&!attackProfiles.get(id)?.error);back.disabled=working;for(const node of fields.querySelectorAll('input,select,textarea'))node.disabled=working;}
 function input(label,value,change,{type='text',min,max,multiple=false}={}){const node=el(type==='textarea'?'textarea':'input');if(type!=='textarea')node.type=type;node.value=value??'';if(min!=null)node.min=min;if(max!=null)node.max=max;node.oninput=()=>{change(type==='number'?Number(node.value):node.value);remember();};fields.append(field(label,node));return node;}
 function select(label,rows,value,change){const node=el('select');node.setAttribute('aria-label',label);node.append(el('option','Выберите…'));node.firstChild.value='';for(const row of rows||[]){const option=el('option',row.name||row.label||row.id);option.value=row.id;node.append(option);}node.value=value||'';node.onchange=protect(async()=>{try{await change(node.value);}finally{remember();buttonState();}});fields.append(field(label,node));return node;}
 function multi(label,rows,selected,change){const box=el('details',undefined,'disclosure'),body=el('div',undefined,'prototype-options'),search=el('input');search.placeholder='Найти';search.setAttribute('aria-label','Найти: '+label);box.append(el('summary',label),search,body);fields.append(box);
  function draw(){body.replaceChildren();const query=search.value.toLocaleLowerCase();for(const row of (rows||[]).filter(row=>((row.name||'')+' '+row.id).toLocaleLowerCase().includes(query))){const checkbox=el('input');checkbox.type='checkbox';checkbox.value=row.id;checkbox.checked=selected.includes(row.id);checkbox.onchange=()=>{selected=selected.filter(id=>id!==row.id);if(checkbox.checked)selected.push(row.id);change(selected);remember();};const line=field((row.name||row.label||row.id)+(row.issue?' · '+row.issue:''),checkbox);line.className='checkline';body.append(line);}}
  search.oninput=draw;draw();return box;
 }
 function draw(){fields.replaceChildren();preview.replaceChildren(el('h2','Лист проверяет Nat20'),el('p','Выберите героя и снаряжение, затем проверьте лист. Ограничения и результат поступят с сервера.','hint'));
  const nameInput=input('Имя героя / название игры',draft.name,value=>draft.name=value);nameInput.readOnly=Boolean(catalogue.adventures.find(row=>row.id===draft.adventure)?.hero_name);
  select('Класс',catalogue.classes,draft.build.class_slug,value=>{draft.build.class_slug=value;delete draft.build.classes;});
  select('Подкласс — если позволяет уровень',catalogue.subclasses,draft.build.subclass_slug,value=>draft.build.subclass_slug=value||null);
  select('Вид',catalogue.species,draft.build.species_slug,value=>draft.build.species_slug=value);
  select('Предыстория',catalogue.backgrounds,draft.build.background_slug,value=>draft.build.background_slug=value||null);
  const level=catalogue.build_schema?.properties?.level||{};input('Уровень',draft.build.level,value=>draft.build.level=value,{type:'number',min:level.minimum,max:level.maximum});
  fields.append(el('h2','Характеристики'));const scores=draft.build.ability_scores??={};for(const [id,label] of Object.entries(abilities))input(label,scores[id],value=>scores[id]=value,{type:'number'});
  multi('Снаряжение',catalogue.items,draft.build.equipment||[],value=>draft.build.equipment=value);
  multi('Опции героя',catalogue.choices,draft.build.selected_choices||[],value=>draft.build.selected_choices=value);
  multi('Подготовленные заклинания',catalogue.spells,draft.prepared_spells||[],value=>draft.prepared_spells=value);
  multi('Участники возможной встречи — до четырёх',catalogue.monsters,draft.encounter_monsters||[],value=>{draft.encounter_monsters=value;drawBonuses();});
  const bonusFields=el('details',undefined,'disclosure');bonusFields.append(el('summary','Параметры встречи из вашего источника'));const bonusBody=el('div');bonusFields.append(bonusBody);fields.append(bonusFields);
  function drawBonuses(){bonusBody.replaceChildren(el('p','Бонус атаки выбранного противника поступает из Native. Для неподдержанного профиля доступен необязательный бонус из вашего проверенного источника.','hint'));draft.encounter_attack_bonuses??={};draft.encounter_attack_sources??={};
   for(const id of draft.encounter_monsters||[]){const name=catalogue.monsters.find(row=>row.id===id)?.name||id,card=el('section'),message=el('p','Получаем профиль Native…','hint');card.dataset.monsterProfile=id;card.append(el('strong',name),message);bonusBody.append(card);
    monsterProfile(id).then(profile=>{if(!card.isConnected)return;message.textContent=profile.status==='native_derived'?'Бонус атаки Native: '+profile.attack_bonus.toLocaleString('ru-RU',{signDisplay:'always'})+'. Ручной ввод не нужен.':'Автоматическая атака пока недоступна: '+(profile.reason||'Native не подтвердил единый профиль атаки.');card.append(el('p','Источник: '+profile.method+' · '+profile.monster+' · SHA '+profile.monster_sha256,'hint'));if(profile.status==='native_derived')return;
     const number=el('input'),source=el('input');number.type='number';number.value=draft.encounter_attack_bonuses[id]??'';number.oninput=()=>{if(number.value==='')delete draft.encounter_attack_bonuses[id];else draft.encounter_attack_bonuses[id]=Number(number.value);remember();};source.value=draft.encounter_attack_sources[id]||'';source.oninput=()=>{draft.encounter_attack_sources[id]=source.value;remember();};card.append(el('p','Авторский бонус необязателен. Без него конкретная неподдержанная атака получит отказ; остальные действия и возможности героя доступны.','hint'),field('Бонус атаки: '+name,number),field('Источник: '+name,source));
    }).catch(error=>{if(!card.isConnected)return;message.textContent='Не удалось получить профиль: '+error.message;const retry=el('button','Повторить проверку профиля');retry.type='button';retry.onclick=()=>{attackProfiles.delete(id);drawBonuses();buttonState();};card.append(retry);}).finally(()=>{if(card.isConnected)buttonState();});
   }
  }drawBonuses();
  fields.append(el('h2','Мир'));select('Приключение или песочница',catalogue.adventures,draft.adventure,async value=>{draft.adventure=value;const row=catalogue.adventures.find(row=>row.id===value);draft.adventure_revision=row?.revision??null;draft.world_run_id=row?.scope==='world'?'pending':null;draft.rules_confirmed=draft.hero_confirmed=draft.background_confirmed=false;draft.source_ruleset=row?.source_ruleset||null;nameInput.readOnly=Boolean(row?.hero_name);if(row?.hero_name){draft.name=row.hero_name;nameInput.value=row.hero_name;}if(row?.scope==='world'){working=true;buttonState();try{const world=await api('/creation/drafts/'+value.slice('prepared:'.length)+'/world-readiness');if(!world.ready||!world.world_ready||world.revision!==row.revision)throw new Error('Мир изменился. Вернитесь к материалам и подтвердите его заново.');draft.world_run_id=world.run_id;draft.mechanics_ruleset='dnd2024';}finally{working=false;draw();}}else draw();});
  if(structuredWorld()){fields.append(el('p','Редакция источника: '+(draft.source_ruleset||'указана в материалах')+'. Мир используется отдельно от правил героя; старые эффекты и противники автоматически не переносятся.','hint'));input('Предыстория героя',draft.hero_background,value=>{draft.hero_background=value;draft.background_confirmed=false;const box=fields.querySelector('#prototype-background-confirm');if(box)box.checked=false;},{type:'textarea'});for(const [id,key,label] of [['prototype-rules-confirm','rules_confirmed','Подтверждаю правила игры D&D 2024 (Nat20)'],['prototype-hero-confirm','hero_confirmed','Подтверждаю выбранного героя'],['prototype-background-confirm','background_confirmed','Подтверждаю предысторию героя']]){const box=el('input');box.id=id;box.type='checkbox';box.checked=Boolean(draft[key]);box.onchange=()=>{draft[key]=box.checked;requestId=null;saveDraft();buttonState();};fields.append(field(label,box));}}
  fields.append(el('p','Для подготовленного мира используется имя, уже подтверждённое в подготовке. Редакция и согласованность героя проверяются сервером.','hint'));
  input('О чём будет история?',draft.description,value=>draft.description=value,{type:'textarea'});
  for(const text of catalogue.limitations||[])fields.append(el('p',text,'hint'));buttonState();
 }
 function drawSheet(value){preview.replaceChildren(el('h2',value.valid?'Лист готов':'Нужно уточнить выбор'));
  if(value.sheet){const s=value.sheet;preview.append(el('p','HP '+s.hp_max+' · КД '+s.ac+' · скорость '+s.base_speed+' футов'));const list=el('dl',undefined,'inspect-properties');for(const [id,score] of Object.entries(s.ability_scores||{}))list.append(el('dt',abilities[id]||id),el('dd',String(score)));preview.append(list);}
  for(const issue of [...(value.issues||[]),...(value.warnings||[])])preview.append(el('p',typeof issue==='string'?issue:issue.message||issue.reason||String(issue),'hint'));
  for(const group of value.choices||[]){const box=el('fieldset');box.append(el('legend',group.label||group.id));if(group.schedule?.length)box.append(el('p',group.schedule.filter(step=>step.count).map(step=>'Уровень '+step.level+': '+step.count+' выбора').join(' · '),'hint'));for(const option of group.options||[]){const chosen=el('input');chosen.type='checkbox';chosen.checked=(draft.build.selected_choices||[]).includes(option.id);chosen.onchange=()=>{draft.build.selected_choices=(draft.build.selected_choices||[]).filter(id=>id!==option.id);if(chosen.checked)draft.build.selected_choices.push(option.id);remember();};const label=field(option.name||option.label||option.id,chosen);label.className='checkline';box.append(label);}preview.append(box);}
 }
 async function open(prepared=null){view('prototype-creation');notice.textContent='Загружаем доступный каталог и возможности конструктора…';working=true;validated=-1;buttonState();try{
  const [data,health]=await Promise.all([api('/prototype/options'),api('/health')]);catalogue=data;mode.textContent=health.llm?.mock?'Offline test mode · ответы тестового Мастера, без облачных запросов.':['ready','configured'].includes(health.readiness?.status)?'Облачный Мастер доступен · действуют лимиты настроенного профиля.':'Облачный Мастер не подключён. Настройте его в разделе «Нейросети и API».';
  if(!draft){try{draft=JSON.parse(localStorage.getItem(key));}catch{}draft??={name:'',build:structuredClone(data.default_build),adventure:data.adventures?.[0]?.id||'',description:'',prepared_spells:[]};}
  if(prepared){const world=await api('/creation/drafts/'+prepared.draft_id+'/world-readiness');if(!world.ready||!world.world_ready||world.revision!==prepared.revision||world.run_id!==prepared.run_id)throw new Error('Мир изменился или не подтверждён. Вернитесь к материалам и проверьте его заново.');const row=data.adventures.find(row=>row.id==='prepared:'+prepared.draft_id);if(!row)throw new Error('Подтверждённый мир пока недоступен для выбора героя.');const same=draft.adventure===row.id&&draft.adventure_revision===world.revision&&draft.world_run_id===world.run_id;draft.adventure=row.id;draft.adventure_revision=world.revision;draft.world_run_id=world.run_id;draft.source_ruleset=world.source_ruleset;draft.mechanics_ruleset='dnd2024';if(row.hero_name)draft.name=row.hero_name;if(!same){draft.rules_confirmed=draft.hero_confirmed=draft.background_confirmed=false;draft.encounter_monsters=[];remember();}else saveDraft();}
  if(!data.adventures.some(row=>row.id===draft.adventure)&&draft.adventure?.startsWith('prepared:')&&pendingLaunch()?.signature===JSON.stringify(launchPayload()))data.adventures.push({id:draft.adventure,name:'Мир начатой игры — завершить запуск',scope:'world',revision:draft.adventure_revision,source_ruleset:draft.source_ruleset});
  draw();notice.textContent=data.message||'Каталог доступен. Наличие записи не гарантирует исполнения каждого её эффекта.';
 }catch(error){notice.textContent=error.message;catalogue=null;}finally{working=false;buttonState();}}
 check.onclick=protect(async()=>{if(working||!catalogue)return;const rev=revision;working=true;notice.textContent='Nat20 проверяет выбранный лист…';buttonState();try{const value=await api('/prototype/build/preview',{build:draft.build,prepared_spells:draft.prepared_spells});if(rev!==revision)return;drawSheet(value);validated=value.valid?rev:-1;notice.textContent=value.valid?'Можно начинать игру.':'Исправьте указанные сервером ограничения и проверьте снова.';}catch(error){notice.textContent=error.message;}finally{working=false;buttonState();}});
 form.onsubmit=protect(async event=>{event.preventDefault();if(working||validated!==revision||!worldConsented())return;const payload=launchPayload(),signature=JSON.stringify(payload),old=pendingLaunch(),pending=old?.signature===signature?old:{signature,request_id:crypto.randomUUID()};requestId=pending.request_id;rememberLaunch(pending);working=true;notice.textContent='Создаём героя и мир…';buttonState();try{
  let value=pending.campaign_id?{id:pending.campaign_id}:null;
  if(!value){if(structuredWorld()){const world=await api('/creation/drafts/'+draft.adventure.slice('prepared:'.length)+'/world-readiness');if(!world.ready||!world.world_ready||world.run_id!==draft.world_run_id)throw new Error('Мир изменился. Вернитесь к материалам и подтвердите актуальный мир.');if(world.revision!==draft.adventure_revision){const current=await api('/creation/drafts/'+draft.adventure.slice('prepared:'.length));if(old?.signature!==signature||!current.campaign)throw new Error('Мир изменился. Вернитесь к материалам и подтвердите актуальный мир.');}}
   value=await api('/prototype/campaigns',{...payload,request_id:requestId});rememberLaunch({...pending,campaign_id:value.id});
  }
  campaignId=value.id;localStorage.setItem('solo-campaign',value.id);await refresh();view('play');localStorage.removeItem(key);localStorage.removeItem(pendingKey);draft=null;validated=-1;
 }catch(error){notice.textContent=error.message;}finally{working=false;buttonState();}});
 const oldCreation=window.soloOpenCreation;importer.onclick=protect(()=>{saveDraft();const id=draft?.adventure?.startsWith('prepared:')?draft.adventure.slice('prepared:'.length):localStorage.getItem('solo-creation-draft');return oldCreation(id||null);});back.onclick=()=>{saveDraft();view('campaigns');};
 api('/prototype/status').then(status=>{if(!status.experimental)return;window.soloPrototypeEnabled=true;$('new-campaign').textContent='Новая игра';$('new-campaign').onclick=protect(()=>open());const welcome=$('welcome')?.querySelector('.chronicle-start .primary');if(welcome){welcome.textContent='Новая игра';welcome.onclick=protect(()=>open());}}).catch(()=>{});
 window.soloOpenNewGame=()=>open();window.soloOpenPreparedNat20=selection=>open(selection);
})();
